golang栈的增长方向
```go
func main() {
	a := 1
	b := 2
	fmt.Println(&a, &b)
}

// output: 0xc00036a2b0 0xc00036a2b8
```

由此可见栈的增长方向是由低地址向高地址增长

```go
func MaxIncrSeq(nums []int) int {
    max := 0
    arr := make([][]int, 0, len(nums))
    for _, num := range nums {
        bj := false
        for j := 0; j < max; j++ {
            if num < arr[j][len(arr[j])-1] {
                t := make([]int, len(arr[j]))
                copy(t, arr[j-1])
                t[len(t)-1] = num
                arr[j] = t
                bj = true
                break
            }
        }
        if !bj {
            t := make([]int, max+1)
            if max != 0 {
                copy(t, arr[len(arr)-1])
            }
            t[max] = num
            arr = append(arr, t)
            max = len(arr)
        }
    }
    return max
}
```


```go
func MaxIncrSeqSize(nums []int) int {
    arr := make([]int, len(nums))
    for i := 0; i < len(arr); i++ {
        arr[i] = math.MaxInt32
    }
    max := 0
    for _, num := range nums {
        for i := 0; i < len(arr); i++ {
            if arr[i] > num {
                arr[i] = num
                if i+1 > max {
                    max = i + 1
                }
                break
            }
        }
    }
    return max
}
```

