			// 注意：需要复制path，因为path会被修改
			temp := make([]int, len(path))
			copy(temp, path)
			result = append(result, temp)
			return
		}

		// 尝试每一个可能的选项
		for i := 0; i < len(nums); i++ {
			// 跳过已经使用过的元素
			if used[i] {
				continue
			}

			// 做选择：将当前元素加入路径
			path = append(path, nums[i])
			used[i] = true

			// 递归：继续选择下一个元素
			backtrack()

			// 撤销选择：回溯到上一步
			path = path[:len(path)-1]
			used[i] = false
		}
	}

	backtrack()
	return result
}

func main() {
	nums := []int{1, 2, 3}
	result := permute(nums)

	fmt.Printf("数组 %v 的全排列:\n", nums)
	for i, perm := range result {
		fmt.Printf("排列 %d: %v\n", i+1, perm)
	}

	// 输出:
	// 数组 [1 2 3] 的全排列:
	// 排列 1: [1 2 3]
	// 排列 2: [1 3 2]
	// 排列 3: [2 1 3]
	// 排列 4: [2 3 1]
	// 排列 5: [3 1 2]
	// 排列 6: [3 2 1]
}
```

