# 双指针（Two Pointers）

双指针技术使用两个指针在数组或字符串中协同工作，通常用于优化暴力解法。

## 快慢指针

快慢指针是双指针的一种，两个指针以不同的速度移动。

### 应用场景

1. **检测链表中的环**：Floyd 判圈算法
2. **找链表的中间节点**
3. **删除链表的倒数第 N 个节点**
4. **数组去重**

### 示例代码

```go
package main

import "fmt"

// LeetCode 141. 环形链表
type ListNode struct {
    Val  int
    Next *ListNode
}

func hasCycle(head *ListNode) bool {
    if head == nil || head.Next == nil {
        return false
    }

    slow, fast := head, head.Next

    for fast != nil && fast.Next != nil {
        if slow == fast {
            return true
        }
        slow = slow.Next
        fast = fast.Next.Next
    }

    return false
}

// LeetCode 142. 环形链表 II - 找环的入口
func detectCycle(head *ListNode) *ListNode {
    if head == nil || head.Next == nil {
        return nil
    }

    slow, fast := head, head

    // 第一步：判断是否有环
    for fast != nil && fast.Next != nil {
        slow = slow.Next
        fast = fast.Next.Next
        if slow == fast {
            break
        }
    }

    if fast == nil || fast.Next == nil {
        return nil // 无环
    }

    // 第二步：找环的入口
    slow = head
    for slow != fast {
        slow = slow.Next
        fast = fast.Next
    }

    return slow
}

// LeetCode 876. 链表的中间结点
func middleNode(head *ListNode) *ListNode {
    slow, fast := head, head

    for fast != nil && fast.Next != nil {
        slow = slow.Next
        fast = fast.Next.Next
    }

    return slow
}

// LeetCode 19. 删除链表的倒数第 N 个结点
func removeNthFromEnd(head *ListNode, n int) *ListNode {
    dummy := &ListNode{Next: head}
    slow, fast := dummy, dummy

    // 快指针先走 n+1 步
    for i := 0; i <= n; i++ {
        fast = fast.Next
    }

    // 快慢指针同时移动，直到快指针到达末尾
    for fast != nil {
        slow = slow.Next
        fast = fast.Next
    }

    // 删除倒数第 n 个节点
    slow.Next = slow.Next.Next

    return dummy.Next
}

// LeetCode 26. 删除有序数组中的重复项
func removeDuplicates(nums []int) int {
    if len(nums) == 0 {
        return 0
    }

    slow := 0
    for fast := 1; fast < len(nums); fast++ {
        if nums[fast] != nums[slow] {
            slow++
            nums[slow] = nums[fast]
        }
    }

    return slow + 1
}

func main() {
    // 数组去重示例
    nums := []int{0, 0, 1, 1, 1, 2, 2, 3, 3, 4}
    length := removeDuplicates(nums)
    fmt.Println("去重后长度:", length)
    fmt.Println("去重后数组:", nums[:length])

    // 输出:
    // 去重后长度: 5
    // 去重后数组: [0 1 2 3 4]
}
```

## 左右指针

左右指针从数组的两端向中间移动，通常用于有序数组或字符串。

### 应用场景

1. **二分查找**
2. **两数之和**（有序数组）
3. **反转数组/字符串**
4. **回文串判断**
5. **盛最多水的容器**

### 示例代码

```go
package main

import (
    "fmt"
    "sort"
)

// LeetCode 167. 两数之和 II - 输入有序数组
func twoSum(numbers []int, target int) []int {
    left, right := 0, len(numbers)-1

    for left < right {
        sum := numbers[left] + numbers[right]
        if sum == target {
            return []int{left + 1, right + 1}
        } else if sum < target {
            left++
        } else {
            right--
        }
    }

    return []int{}
}

// LeetCode 344. 反转字符串
func reverseString(s []byte) {
    left, right := 0, len(s)-1

    for left < right {
        s[left], s[right] = s[right], s[left]
        left++
        right--
    }
}

// LeetCode 125. 验证回文串
func isPalindrome(s string) bool {
    left, right := 0, len(s)-1

    for left < right {
        // 跳过非字母数字字符
        for left < right && !isAlphanumeric(s[left]) {
            left++
        }
        for left < right && !isAlphanumeric(s[right]) {
            right--
        }

        if toLower(s[left]) != toLower(s[right]) {
            return false
        }

        left++
        right--
    }

    return true
}

func isAlphanumeric(c byte) bool {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func toLower(c byte) byte {
    if c >= 'A' && c <= 'Z' {
        return c + 32
    }
    return c
}

// LeetCode 11. 盛最多水的容器
func maxArea(height []int) int {
    left, right := 0, len(height)-1
    maxArea := 0

    for left < right {
        // 计算当前面积
        width := right - left
        h := height[left]
        if height[right] < h {
            h = height[right]
        }
        area := width * h

        if area > maxArea {
            maxArea = area
        }

        // 移动较小的指针
        if height[left] < height[right] {
            left++
        } else {
            right--
        }
    }

    return maxArea
}

// LeetCode 15. 三数之和
func threeSum(nums []int) [][]int {
    n := len(nums)
    if n < 3 {
        return [][]int{}
    }

    sort.Ints(nums)
    result := make([][]int, 0)

    for i := 0; i < n-2; i++ {
        // 跳过重复元素
        if i > 0 && nums[i] == nums[i-1] {
            continue
        }

        left, right := i+1, n-1
        target := -nums[i]

        for left < right {
            sum := nums[left] + nums[right]
            if sum == target {
                result = append(result, []int{nums[i], nums[left], nums[right]})

                // 跳过重复元素
                for left < right && nums[left] == nums[left+1] {
                    left++
                }
                for left < right && nums[right] == nums[right-1] {
                    right--
                }

                left++
                right--
            } else if sum < target {
                left++
            } else {
                right--
            }
        }
    }

    return result
}

func main() {
    // 两数之和示例
    numbers := []int{2, 7, 11, 15}
    target := 9
    fmt.Println("两数之和:", twoSum(numbers, target))

    // 三数之和示例
    nums := []int{-1, 0, 1, 2, -1, -4}
    fmt.Println("三数之和:", threeSum(nums))

    // 盛水容器示例
    height := []int{1, 8, 6, 2, 5, 4, 8, 3, 7}
    fmt.Println("最大面积:", maxArea(height))

    // 输出:
    // 两数之和: [1 2]
    // 三数之和: [[-1 -1 2] [-1 0 1]]
    // 最大面积: 49
}
```

