# 滑动窗口（Sliding Window）

## 基本概念

滑动窗口是一种在数组或字符串上维护一个窗口的技术，通过移动窗口的左右边界来解决问题。滑动窗口主要分为两种类型：

1. **固定窗口**：窗口大小固定不变
2. **可变窗口**：窗口大小根据条件动态变化

### 核心思想

- 使用两个指针（left 和 right）表示窗口的左右边界
- 通过移动右指针扩展窗口，移动左指针收缩窗口
- 在窗口移动过程中维护窗口的状态（如和、最大值、字符计数等）

## 固定窗口

窗口大小固定为 k，每次移动一个位置。

### 算法模板

```go
func fixedWindow(nums []int, k int) {
    n := len(nums)
    if n < k {
        return
    }

    // 初始化窗口 [0, k-1]
    windowSum := 0
    for i := 0; i < k; i++ {
        windowSum += nums[i]
    }

    // 滑动窗口
    for i := k; i < n; i++ {
        // 处理当前窗口
        // ...

        // 移动窗口：移除左边界，添加右边界
        windowSum = windowSum - nums[i-k] + nums[i]
    }
}
```

### 示例：滑动窗口最大值

```go
package main

import "fmt"

// LeetCode 239. 滑动窗口最大值
func maxSlidingWindow(nums []int, k int) []int {
    n := len(nums)
    if n == 0 || k == 0 {
        return []int{}
    }

    result := make([]int, 0, n-k+1)

    // 使用双端队列存储索引，保持队列中元素单调递减
    deque := make([]int, 0)

    for i := 0; i < n; i++ {
        // 移除窗口外的元素
        for len(deque) > 0 && deque[0] <= i-k {
            deque = deque[1:]
        }

        // 移除小于当前元素的元素，保持单调递减
        for len(deque) > 0 && nums[deque[len(deque)-1]] < nums[i] {
            deque = deque[:len(deque)-1]
        }

        deque = append(deque, i)

        // 窗口形成后，记录最大值
        if i >= k-1 {
            result = append(result, nums[deque[0]])
        }
    }

    return result
}

// 固定窗口：计算大小为k的窗口的平均值
func averageOfSubarrays(nums []int, k int) []float64 {
    n := len(nums)
    if n < k {
        return []float64{}
    }

    result := make([]float64, 0, n-k+1)
    windowSum := 0

    // 初始化第一个窗口
    for i := 0; i < k; i++ {
        windowSum += nums[i]
    }
    result = append(result, float64(windowSum)/float64(k))

    // 滑动窗口
    for i := k; i < n; i++ {
        windowSum = windowSum - nums[i-k] + nums[i]
        result = append(result, float64(windowSum)/float64(k))
    }

    return result
}

func main() {
    nums := []int{1, 3, -1, -3, 5, 3, 6, 7}
    k := 3

    fmt.Println("滑动窗口最大值:", maxSlidingWindow(nums, k))
    fmt.Println("滑动窗口平均值:", averageOfSubarrays(nums, k))

    // 输出:
    // 滑动窗口最大值: [3 3 5 5 6 7]
    // 滑动窗口平均值: [1 1.66667 0.333333 1.66667 3.66667 5.33333]
}
```

## 可变窗口

窗口大小根据条件动态变化，通常用于找满足条件的子数组/子字符串。

### 算法模板

```go
func variableWindow(nums []int) {
    left := 0
    window := make(map[int]int) // 或使用其他数据结构维护窗口状态

    for right := 0; right < len(nums); right++ {
        // 扩展窗口：添加 nums[right]
        window[nums[right]]++

        // 收缩窗口：当窗口不满足条件时
        while (窗口不满足条件) {
            // 移除 nums[left]
            window[nums[left]]--
            if window[nums[left]] == 0 {
                delete(window, nums[left])
            }
            left++
        }

        // 更新结果
        // ...
    }
}
```

### 示例：无重复字符的最长子串

```go
// LeetCode 3. 无重复字符的最长子串
func lengthOfLongestSubstring(s string) int {
    if len(s) == 0 {
        return 0
    }

    left := 0
    maxLen := 0
    charMap := make(map[byte]int)

    for right := 0; right < len(s); right++ {
        // 扩展窗口
        charMap[s[right]]++

        // 收缩窗口：当窗口中有重复字符时
        for charMap[s[right]] > 1 {
            charMap[s[left]]--
            if charMap[s[left]] == 0 {
                delete(charMap, s[left])
            }
            left++
        }

        // 更新最大长度
        if right-left+1 > maxLen {
            maxLen = right - left + 1
        }
    }

    return maxLen
}

// LeetCode 209. 长度最小的子数组
func minSubArrayLen(target int, nums []int) int {
    left := 0
    sum := 0
    minLen := len(nums) + 1

    for right := 0; right < len(nums); right++ {
        // 扩展窗口
        sum += nums[right]

        // 收缩窗口：当窗口和 >= target 时
        for sum >= target {
            // 更新最小长度
            if right-left+1 < minLen {
                minLen = right - left + 1
            }
            // 收缩左边界
            sum -= nums[left]
            left++
        }
    }

    if minLen > len(nums) {
        return 0
    }
    return minLen
}

// LeetCode 76. 最小覆盖子串
func minWindow(s string, t string) string {
    if len(s) < len(t) {
        return ""
    }

    // 统计 t 中每个字符的出现次数
    need := make(map[byte]int)
    for i := 0; i < len(t); i++ {
        need[t[i]]++
    }

    left := 0
    valid := 0 // 窗口中满足条件的字符数量
    window := make(map[byte]int)
    start, minLen := 0, len(s)+1

    for right := 0; right < len(s); right++ {
        c := s[right]

        // 扩展窗口
        if need[c] > 0 {
            window[c]++
            if window[c] == need[c] {
                valid++
            }
        }

        // 收缩窗口：当窗口包含 t 的所有字符时
        for valid == len(need) {
            // 更新最小窗口
            if right-left+1 < minLen {
                start = left
                minLen = right - left + 1
            }

            // 收缩左边界
            d := s[left]
            left++
            if need[d] > 0 {
                if window[d] == need[d] {
                    valid--
                }
                window[d]--
            }
        }
    }

    if minLen > len(s) {
        return ""
    }
    return s[start : start+minLen]
}
