    // 去重后长度: 5
    // 去重后数组: [0 1 2 3 4]
}
```

## 左右指针

左右指针从数组的两端向中间移动，通常用于有序数组或字符串。

### 应用场景

1. **二分查找**
2. **两数之和**（有序数组）
3. **反转数组/字符串**
4. **回文串判断**
5. **盛最多水的容器**

### 示例代码

```go
package main

import (
    "fmt"
    "sort"
)

// LeetCode 167. 两数之和 II - 输入有序数组
func twoSum(numbers []int, target int) []int {
    left, right := 0, len(numbers)-1

    for left < right {
        sum := numbers[left] + numbers[right]
        if sum == target {
            return []int{left + 1, right + 1}
        } else if sum < target {
            left++
        } else {
            right--
        }
    }

    return []int{}
}

// LeetCode 344. 反转字符串
func reverseString(s []byte) {
    left, right := 0, len(s)-1

    for left < right {
        s[left], s[right] = s[right], s[left]
        left++
        right--
    }
}

// LeetCode 125. 验证回文串
func isPalindrome(s string) bool {
    left, right := 0, len(s)-1

    for left < right {
        // 跳过非字母数字字符
        for left < right && !isAlphanumeric(s[left]) {
            left++
        }
        for left < right && !isAlphanumeric(s[right]) {
            right--
        }

        if toLower(s[left]) != toLower(s[right]) {
            return false
        }

        left++
        right--
    }

    return true
}

func isAlphanumeric(c byte) bool {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func toLower(c byte) byte {
    if c >= 'A' && c <= 'Z' {
        return c + 32
    }
    return c
}

// LeetCode 11. 盛最多水的容器
func maxArea(height []int) int {
    left, right := 0, len(height)-1
    maxArea := 0

    for left < right {
        // 计算当前面积
        width := right - left
        h := height[left]
        if height[right] < h {
            h = height[right]
        }
        area := width * h

        if area > maxArea {
            maxArea = area
        }

        // 移动较小的指针
        if height[left] < height[right] {
            left++
        } else {
            right--
        }
    }

    return maxArea
}

// LeetCode 15. 三数之和
func threeSum(nums []int) [][]int {
    n := len(nums)
    if n < 3 {
        return [][]int{}
    }

    sort.Ints(nums)
    result := make([][]int, 0)

    for i := 0; i < n-2; i++ {
        // 跳过重复元素
        if i > 0 && nums[i] == nums[i-1] {
            continue
        }

        left, right := i+1, n-1
        target := -nums[i]

        for left < right {
            sum := nums[left] + nums[right]
            if sum == target {
                result = append(result, []int{nums[i], nums[left], nums[right]})

                // 跳过重复元素
                for left < right && nums[left] == nums[left+1] {
                    left++
                }
                for left < right && nums[right] == nums[right-1] {
                    right--
                }

                left++
                right--
            } else if sum < target {
                left++
            } else {
                right--
            }
        }
    }

    return result
}

func main() {
    // 两数之和示例
    numbers := []int{2, 7, 11, 15}
    target := 9
    fmt.Println("两数之和:", twoSum(numbers, target))

    // 三数之和示例
    nums := []int{-1, 0, 1, 2, -1, -4}
    fmt.Println("三数之和:", threeSum(nums))

    // 盛水容器示例
    height := []int{1, 8, 6, 2, 5, 4, 8, 3, 7}
    fmt.Println("最大面积:", maxArea(height))

    // 输出:
    // 两数之和: [1 2]
    // 三数之和: [[-1 -1 2] [-1 0 1]]
    // 最大面积: 49
}
```

---

# 算法对比与选择

## 滑动窗口 vs 双指针

| 特性 | 滑动窗口 | 双指针 |
|------|---------|--------|
| **适用场景** | 子数组/子字符串问题 | 有序数组、链表问题 |
| **窗口性质** | 通常维护连续区间 | 可以是任意两个位置 |
| **移动方式** | 左右边界协同移动 | 根据条件独立移动 |
| **典型问题** | 最长无重复子串、最小覆盖子串 | 两数之和、反转数组 |

## 选择建议

- **使用滑动窗口**：
  - 需要找满足条件的连续子数组/子字符串
  - 需要维护窗口内的状态（如字符计数、和等）
  - 问题涉及"最长"、"最短"、"包含"等关键词

- **使用快慢指针**：
  - 链表相关问题（环检测、找中点）
  - 数组去重、移动零等问题

- **使用左右指针**：
  - 有序数组的查找问题
  - 需要从两端向中间移动的问题
  - 回文串、反转等问题

---

# 时间复杂度分析

- **滑动窗口**：O(n)，每个元素最多被访问两次（左指针和右指针各一次）
- **双指针**：O(n)，两个指针总共遍历数组一次

---

# 总结

滑动窗口和双指针是解决数组/字符串问题的高效技巧：

1. **滑动窗口**适合处理连续子区间问题，通过维护窗口状态来优化
2. **快慢指针**适合处理链表和数组的特定位置问题
3. **左右指针**适合处理有序数组的查找和比较问题

掌握这些技巧可以显著提高解题效率，避免暴力解法的 O(n²) 或更高时间复杂度。

