```go
// LeetCode 84. 柱状图中最大的矩形
func largestRectangleArea(heights []int) int {
    n := len(heights)
    stack := make([]int, 0)
    maxArea := 0

    for i := 0; i <= n; i++ {
        // 在最后添加一个高度为0的柱子，确保所有柱子都能被处理
        var h int
        if i < n {
            h = heights[i]
        } else {
            h = 0
        }

        // 维护递增栈
        for len(stack) > 0 && heights[stack[len(stack)-1]] > h {
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]

            // 计算以 heights[top] 为高的矩形面积
            width := i
            if len(stack) > 0 {
                width = i - stack[len(stack)-1] - 1
            }
            area := heights[top] * width
            if area > maxArea {
                maxArea = area
            }
        }
        stack = append(stack, i)
    }

    return maxArea
}

func main() {
    heights := []int{2, 1, 5, 6, 2, 3}
    fmt.Println("柱状图高度:", heights)
    fmt.Println("最大矩形面积:", largestRectangleArea(heights))
    // 输出: 10
}
```

## 4. 接雨水问题

**问题描述**：给定 n 个非负整数表示每个宽度为 1 的柱子的高度图，计算按此排列的柱子，下雨之后能接多少雨水。

```go
// LeetCode 42. 接雨水
func trap(height []int) int {
    stack := make([]int, 0) // 存储索引，递减栈
    water := 0

    for i := 0; i < len(height); i++ {
        // 当前高度大于栈顶高度，形成凹槽
        for len(stack) > 0 && height[stack[len(stack)-1]] < height[i] {
            bottom := stack[len(stack)-1]
            stack = stack[:len(stack)-1]

            if len(stack) == 0 {
                break
            }

            // 计算雨水面积
            left := stack[len(stack)-1]
            width := i - left - 1
            h := min(height[left], height[i]) - height[bottom]
            water += width * h
        }
        stack = append(stack, i)
    }

    return water
}

func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}

func main() {
    height := []int{0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1}
    fmt.Println("高度数组:", height)
    fmt.Println("接水量:", trap(height))
    // 输出: 6
}
```

