```go
type semaProfileFlags int

const (
	semaBlockProfile semaProfileFlags = 1 << iota
	semaMutexProfile
)
```

信号树堆示意图

![信号树堆](https://blog-1251474779.cos.ap-beijing.myqcloud.com/statics/sema-队列.svg)

## 添加信号树堆
将当期协程存放入树堆中，等待被唤醒
```go
// 信号量处理 等待被唤醒
func semacquire1(addr *uint32, lifo bool, profile semaProfileFlags, skipframes int, reason waitReason) {
	gp := getg()
	if gp != gp.m.curg {
		throw("semacquire not on the G stack")
	}

	// Easy case.
	if cansemacquire(addr) {
		// 如果有正在执行 semrelease1 直接获取信号量 返回
		return
	}

	s := acquireSudog()
	root := semtable.rootFor(addr)
	t0 := int64(0)
	s.releasetime = 0
	s.acquiretime = 0
	s.ticket = 0
	if profile&semaBlockProfile != 0 && blockprofilerate > 0 {
		// 阻塞事件
		t0 = cputicks()
		// 阻塞没有释放时间
		s.releasetime = -1
	}
	if profile&semaMutexProfile != 0 && mutexprofilerate > 0 {
		// 锁事件
		if t0 == 0 {
			t0 = cputicks()
		}
		// 记录获取时间
		s.acquiretime = t0
	}
	for {
		// 锁住
		lockWithRank(&root.lock, lockRankRoot)
		// 添加root的等待者
		root.nwait.Add(1)
		if cansemacquire(addr) {
			// 再次检测是否有正在释放的信号量
			root.nwait.Add(-1)
			unlock(&root.lock)
			break
		}
		// 入队 休眠
		root.queue(addr, s, lifo)
		// 等待被唤醒
		goparkunlock(&root.lock, reason, traceEvGoBlockSync, 4+skipframes)
		if s.ticket != 0 || cansemacquire(addr) {
			// 已经获取过 或 addr 还可以获取 sema
			break
		}
	}
	// 被唤醒后是否记录阻塞事件
	if s.releasetime > 0 {
		// 尝试记录阻塞事件
		blockevent(s.releasetime-t0, 3+skipframes)
	}
	releaseSudog(s)
}
```

## 移除信号树堆
唤醒等待协程
```go
// 解锁单个 addr 的等待 g 并唤醒该 g
func semrelease1(addr *uint32, handoff bool, skipframes int) {
	// 取根结点
	root := semtable.rootFor(addr)
	// 增加信号量
	atomic.Xadd(addr, 1)

	// 检测操作必须在 xadd 后面
	// 避免错过唤醒
	// 这边加上 那边获取
	if root.nwait.Load() == 0 {
		// 没有等待的 g 直接返回
		return
	}

	lockWithRank(&root.lock, lockRankRoot)
	if root.nwait.Load() == 0 {
		// 二次检测
		unlock(&root.lock)
		return
	}
	// 从树中弹出一个 sudog
	s, t0 := root.dequeue(addr)
	if s != nil {
		// 弹出有效
		root.nwait.Add(-1)
	}
	unlock(&root.lock)
	if s != nil { // May be slow or even yield, so unlock first
		acquiretime := s.acquiretime
		if acquiretime != 0 {
			// 有 acquiretime 表示是锁事件 尝试记录锁事件
			mutexevent(t0-acquiretime, 3+skipframes)
		}
		if s.ticket != 0 {
			throw("corrupted semaphore ticket")
		}
		if handoff && cansemacquire(addr) {
			// 只有外部需要让出调度时才会获取信号量
			// 标记下次执行 并且 addr还可以被获取
			s.ticket = 1
		}
		// 唤醒s 加入就绪队列
		readyWithTime(s, 5+skipframes)
		if s.ticket == 1 && getg().m.locks == 0 {
			// 标记为1 并且 m 没有被其他 g 锁住
			// 让出 m 等待下次调度
			// 即直接调度 s 对应的 g
			// 请注意，继承了我们的时间片：这是可取的，以避免一个高度竞争的信号量无限期地占用 P
			// goyield 类似于 Gosched，但它会发出一个“抢占式”跟踪事件
			// 更重要的是，将当前 G 放在本地 runq 而不是全局 runq 上
			// 我们只在饥饿状态下执行此操作（handoff=true）
			// 因为在非饥饿情况下，在我们让出调度时，其他服务员可能会获取信号量，这将是一种浪费
			// 相反，我们等待进入饥饿状态，然后我们开始直接切换票和 P
			goyield()
		}
	}
}
```

## 信号入队
```go
// 将当前的 s 入队
// 只有新插入的 addr 才会生成 ticket
func (root *semaRoot) queue(addr *uint32, s *sudog, lifo bool) {
	s.g = getg()
	s.elem = unsafe.Pointer(addr)
	s.next = nil
	s.prev = nil

	// 先查找有没有相同锁地址 有就按规则插入后返回
	var last *sudog
	// var pt **sudog
	pt := &root.treap
	for t := *pt; t != nil; t = *pt {
		// 遍历所有节点 查找 addr 是否已经入 treap
		if t.elem == unsafe.Pointer(addr) {
			// Already have addr in list.
			if lifo {
				// 插入队首
				// Substitute s in t's place in treap.
				// 赋值pt
				*pt = s
				// 交接二叉树链接信息
				s.ticket = t.ticket
				// 使用最开始的获取时间
				s.acquiretime = t.acquiretime
				s.parent = t.parent
				s.prev = t.prev
				s.next = t.next
				if s.prev != nil {
					s.prev.parent = s
				}
				if s.next != nil {
					s.next.parent = s
				}
				// 修正队首尾
				// Add t first in s's wait list.
				s.waitlink = t
				s.waittail = t.waittail
				if s.waittail == nil {
					s.waittail = t
				}
				// 清空原树节点 树相关信息
				t.parent = nil
				t.prev = nil
				t.next = nil
				t.waittail = nil
			} else {
				// 直接插入队尾
				// Add s to end of t's wait list.
				if t.waittail == nil {
					t.waitlink = s
				} else {
					t.waittail.waitlink = s
				}
				t.waittail = s
				s.waitlink = nil
			}
			// 修改后 就返回
			return
		}
		// 向下个节点偏移 根据地址 决定向前向后
		last = t
		if uintptr(unsafe.Pointer(addr)) < uintptr(t.elem) {
			pt = &t.prev
		} else {
			pt = &t.next
		}
	}

	// 新的锁就新建一个二叉树节点
	// ticket 有与0作比较 所以必须大于0
	s.ticket = fastrand() | 1
	// last 作为新叶子节点的父节点
	s.parent = last
	// 将 s 置入 pt 插入新节点
	*pt = s

	// 插入新节点 需要保持优先级的平衡性
	// 利用 ticket 确定优先级
	for s.parent != nil && s.parent.ticket > s.ticket {
		if s.parent.prev == s {
			// s 是左子树 就右旋
			root.rotateRight(s.parent)
		} else {
			if s.parent.next != s {
				panic("semaRoot queue")
			}
			// s 是右子树 就左旋
			root.rotateLeft(s.parent)
		}
	}
}
```

## 信号出队
```go
// 出队单个sudog
// 如果正在分析 sudog 则 dequeue 将返回唤醒它的时间
// 否则返为0
// dequeue searches for and finds the first goroutine
// in semaRoot blocked on addr.
// If the sudog was being profiled, dequeue returns the time
// at which it was woken up as now. Otherwise now is 0.
func (root *semaRoot) dequeue(addr *uint32) (found *sudog, now int64) {
	ps := &root.treap
	s := *ps
	for ; s != nil; s = *ps {
		if s.elem == unsafe.Pointer(addr) {
			// 找到才执行出队操作
			goto Found
		}
		if uintptr(unsafe.Pointer(addr)) < uintptr(s.elem) {
			ps = &s.prev
		} else {
			ps = &s.next
		}
	}
	// 找不到直接返回
	return nil, 0

Found:
	now = int64(0)
	if s.acquiretime != 0 {
		now = cputicks()
	}
	if t := s.waitlink; t != nil {
		// 有链表元素 直接移除队首元素 不用删树节点
		*ps = t
		t.ticket = s.ticket
		t.parent = s.parent
		t.prev = s.prev
		if t.prev != nil {
			t.prev.parent = t
		}
		t.next = s.next
		if t.next != nil {
			t.next.parent = t
		}
		if t.waitlink != nil {
			t.waittail = s.waittail
		} else {
			t.waittail = nil
		}
		// 重置获取时间
		t.acquiretime = now
		s.waitlink = nil
		s.waittail = nil
	} else {
		// 没有后续链表元素 需要删除树节点 进行树的再平衡
		// 向下旋转为叶子节点 然后删除
		for s.next != nil || s.prev != nil {
			// 有非空子树 就进行旋转 将 s 旋转为叶子节点
			if s.next == nil || s.prev != nil && s.prev.ticket < s.next.ticket {
				// 左右子树皆不为空时 需要判断 左右节点的 ticket 保证优先级高度
				root.rotateRight(s)
			} else {
				// 否则 左旋
				root.rotateLeft(s)
			}
		}
		// 左右子树皆为空 即叶子节点 可以安全删除
		// Remove s, now a leaf.
		if s.parent != nil {
			// 有父节点 移除父节点指向
			if s.parent.prev == s {
				s.parent.prev = nil
			} else {
				s.parent.next = nil
			}
		} else {
			// 没有父节点 说明是最后一个节点
			root.treap = nil
		}
	}
	// 清理 s 无关数据
	s.parent = nil
	s.elem = nil
	s.next = nil
	s.prev = nil
	// 出队清空 ticket
	s.ticket = 0
	return s, now
}
```

## 树堆左旋
![左旋](https://blog-1251474779.cos.ap-beijing.myqcloud.com/statics/sema-左旋.svg)
```go
/*

  x                  y
 / \                / \
a   y      -->     x   c
   / \            / \
  b   c          a   b

*/

// rotateLeft rotates the tree rooted at node x.
// turning (x a (y b c)) into (y (x a b) c).
func (root *semaRoot) rotateLeft(x *sudog) {
	// p -> (x a (y b c))
	p := x.parent
	y := x.next
	b := y.prev

	y.prev = x
	x.parent = y
	x.next = b
	if b != nil {
		b.parent = x
	}

	y.parent = p
	if p == nil {
		root.treap = y
	} else if p.prev == x {
		p.prev = y
	} else {
		if p.next != x {
			throw("semaRoot rotateLeft")
		}
		p.next = y
	}
}
```

## 树堆右旋
![右旋](https://blog-1251474779.cos.ap-beijing.myqcloud.com/statics/sema-右旋.svg)
```go
/*

    y              x
   / \            / \
  x   c    -->   a   y
 / \                / \
a   b              b   c

*/
// rotateRight rotates the tree rooted at node y.
// turning (y (x a b) c) into (x a (y b c)).
func (root *semaRoot) rotateRight(y *sudog) {
	// p -> (y (x a b) c)
	p := y.parent
	x := y.prev
	b := x.next

	x.next = y
	y.parent = x
	y.prev = b
	if b != nil {
		b.parent = y
	}

	x.parent = p
	if p == nil {
		root.treap = x
	} else if p.prev == y {
		p.prev = x
	} else {
		if p.next != y {
			throw("semaRoot rotateRight")
		}
		p.next = x
	}
}
