golang 版本：go version go1.15.2 darwin/amd64

根据启动函数来分析golang MPG的生存周期，忽略cgo相关代码。

# MPG
MPG是golang调度的重要对象：
* M，表示一个内核线程，是执行用户代码的实际场所
* P，表示一个处理器，管理M需要运行G的相关资源，如内存分配，G的可执行列表，G的空闲列表等
* G，表示一个goroutine，调度基本单元，维护goroutine内部资源，如栈信息，defer列表等

# 启动
启动汇编函数
```asm
// runtime/asm_amd64.s

TEXT runtime·rt0_go(SB),NOSPLIT,$0
    // ... 省略 ...

	// create istack out of the given (operating system) stack.
	// _cgo_init may update stackguard.
	// 给 runtime.g0 创建栈
	MOVQ	$runtime·g0(SB), DI
	LEAQ	(-64*1024+104)(SP), BX
	MOVQ	BX, g_stackguard0(DI)
	MOVQ	BX, g_stackguard1(DI)
	MOVQ	BX, (g_stack+stack_lo)(DI)
	MOVQ	SP, (g_stack+stack_hi)(DI)

    // ... 省略 ...

	// set the per-goroutine and per-mach "registers"
	get_tls(BX)
	LEAQ	runtime·g0(SB), CX
	MOVQ	CX, g(BX)
	LEAQ	runtime·m0(SB), AX

	// save m->g0 = g0
	// 绑定 m0 和 g0
	MOVQ	CX, m_g0(AX)
	// save m0 to g0->m
	MOVQ	AX, g_m(CX)

	CLD				// convention is D is always left cleared
	CALL	runtime·check(SB)

	MOVL	16(SP), AX		// copy argc
	MOVL	AX, 0(SP)
	MOVQ	24(SP), AX		// copy argv
	MOVQ	AX, 8(SP)
	CALL	runtime·args(SB)       // 解析命令行参数
	CALL	runtime·osinit(SB)     // 获取CPU核数
	CALL	runtime·schedinit(SB)  // 初始化调度

	// create a new goroutine to start program
	MOVQ	$runtime·mainPC(SB), AX		// entry
	PUSHQ	AX
	PUSHQ	$0			// arg size
	CALL	runtime·newproc(SB)// 执行runtime.main
	POPQ	AX
	POPQ	AX

	// start this M
	CALL	runtime·mstart(SB) // 启动m0

	CALL	runtime·abort(SB)	// mstart should never return
	RET
```

`rt0_go`函数主要流程：
* 初始化`g0`、`m0`
* `g0`和`m0`互相绑定
* 初始化相关数据，初始化指定个数的`p`
* 创建新`g`绑定`runtime.main`函数，加入`p`的可执行列表中
* 启动`m0`开始循环调度。

## schedinit
```go
// runtime/proc.go

func schedinit() {
	// ... 省略 ...

	_g_ := getg() // 获取当前绑定的g

	// 限制M的数量
	sched.maxmcount = 10000

	// ... 省略 ...

    // 创建 p
	lock(&sched.lock)
	sched.lastpoll = uint64(nanotime())
	procs := ncpu
	if n, ok := atoi32(gogetenv("GOMAXPROCS")); ok && n > 0 {
		procs = n
	}
	if procresize(procs) != nil {
		throw("unknown runnable goroutine during bootstrap")
	}
	unlock(&sched.lock)
}
```

`schedinit`函数主要流程：
* 初始化全局调度相关值
* 限制`m`的最多个数
* 初始化指定个数的`p`

## newproc
```go
// runtime/proc.go

func newproc(siz int32, fn *funcval) {
	argp := add(unsafe.Pointer(&fn), sys.PtrSize)
	gp := getg()
	pc := getcallerpc()
	systemstack(func() {
		newg := newproc1(fn, argp, siz, gp, pc)

		_p_ := getg().m.p.ptr()
		runqput(_p_, newg, true)

		if mainStarted { // mainStarted 是在 runtime.main 中设置为 true 
			wakep() // 尝试找一个p绑定m
		}
	})
}
```

`newproc`函数主要流程：
* 创建栈大小为`siz`的新`g`，并关联`fn`
* 将新`g`存放于`_p_`的可执行队列中
* 此时刚初始化，并没有执行`runtime.main`所以不会执行`wakep`

```go
// runtime/proc.go

func newproc1(fn *funcval, argp unsafe.Pointer, narg int32, callergp *g, callerpc uintptr) *g {
	_g_ := getg()

	acquirem() // disable preemption because it can be holding p in a local var
	siz := narg
	siz = (siz + 7) &^ 7

	_p_ := _g_.m.p.ptr() // 获取 p
	newg := gfget(_p_)   // 从 p 的空闲 g 列表中获取 g
	if newg == nil {     // 没有空闲的 g
		newg = malg(_StackMin)           // 创建一个拥有最小栈的 g
		casgstatus(newg, _Gidle, _Gdead) // 转换状态
		allgadd(newg)                    // 向全局 g 列表中添加 g
	}

	// ... 省略 ...

    // 填充 g
	memclrNoHeapPointers(unsafe.Pointer(&newg.sched), unsafe.Sizeof(newg.sched))
	newg.sched.sp = sp
	newg.stktopsp = sp
	newg.sched.pc = funcPC(goexit) + sys.PCQuantum // 当g执行完后的处理函数
	newg.sched.g = guintptr(unsafe.Pointer(newg))
	gostartcallfn(&newg.sched, fn)
	newg.gopc = callerpc
	newg.ancestors = saveAncestors(callergp)
	newg.startpc = fn.fn
	if _g_.m.curg != nil {
		newg.labels = _g_.m.curg.labels
	}
	if isSystemGoroutine(newg, false) {
		atomic.Xadd(&sched.ngsys, +1)
	}
	casgstatus(newg, _Gdead, _Grunnable) // 切换成可执行状态

    // 分配goid，如果没有则向p批量获取
	if _p_.goidcache == _p_.goidcacheend {
		_p_.goidcache = atomic.Xadd64(&sched.goidgen, _GoidCacheBatch)
		_p_.goidcache -= _GoidCacheBatch - 1
		_p_.goidcacheend = _p_.goidcache + _GoidCacheBatch
	}
	newg.goid = int64(_p_.goidcache)
	_p_.goidcache++

	releasem(_g_.m)

	return newg
}
```

`newproc1`函数主要流程：
* 从空闲`g`列表中获取或新建`g`，将`g`的信息填充

