## startm
除了m0是汇编初始化的，其他的m都是由startm创建的。
```go
func startm(_p_ *p, spinning bool) {
	lock(&sched.lock)
	if _p_ == nil { // _p_ 为空
		_p_ = pidleget() // 从p空闲列表中获取一个
		if _p_ == nil {  // 获取失败
			unlock(&sched.lock)
			if spinning {
				// 如果是自旋状态，调用方增加了nmspinning，但是没有空闲的P，因此可以取消增量并放弃
				if int32(atomic.Xadd(&sched.nmspinning, -1)) < 0 {
					throw("startm: negative nmspinning")
				}
			}
			return
		}
	}
	mp := mget() // 从m空闲列表中获取m
	if mp == nil { // 如果空闲列表没有
		id := mReserveID() // 获取 m id
		unlock(&sched.lock)

		var fn func()
		if spinning {
			fn = mspinning // 设置 m 的自旋状态函数
		}
		newm(fn, _p_, id) // 创建一个m对象
		return
	}
	unlock(&sched.lock)
	if mp.spinning {
		throw("startm: m is spinning")
	}
	if mp.nextp != 0 {
		throw("startm: m has p")
	}
	if spinning && !runqempty(_p_) {
		throw("startm: p has runnable gs")
	}
	// 由调用者确定是否自旋，并将m.nextp设置为p
	mp.spinning = spinning
	mp.nextp.set(_p_)
	notewakeup(&mp.park)
}
```

`startm`函数主要流程：
* 获取一个`p`，失败则返回
  * 获取一个`m`，如果失败就创建`m`并返回
* `m`暂存`p`

