```go
func goexit0(gp *g) {
	_g_ := getg()

    // 切换g的状态 
    casgstatus(gp, _Grunning, _Gdead)
    // 标记系统goroutine 
    if isSystemGoroutine(gp, false) {
       atomic.Xadd(&sched.ngsys, -1)
    }
	// 清理gp相关的数据
	gp.m = nil
	locked := gp.lockedm != 0
	gp.lockedm = 0
	_g_.m.lockedg = 0
	gp.preemptStop = false
	gp.paniconfault = false
	gp._defer = nil // should be true already but just in case.
	gp._panic = nil // non-nil for Goexit during panic. points at stack-allocated data.
	gp.writebuf = nil
	gp.waitreason = 0
	gp.param = nil
	gp.labels = nil
	gp.timer = nil

	dropg() // 解绑当前m和gp

	if GOARCH == "wasm" { // no threads yet on wasm
		gfput(_g_.m.p.ptr(), gp) // 将gp存放到p的空闲列表中
		schedule() // 下一次调度
	}

	gfput(_g_.m.p.ptr(), gp) // 将gp存放到p的空闲列表中
	if locked {
		// 如果gp锁定了m，则将这个m杀死
		if GOOS != "plan9" { 
			gogo(&_g_.m.g0.sched)
		} else {
			_g_.m.lockedExt = 0
		}
	}
	schedule() // 下一次调度
}
```

`goexit0`函数主要流程：
* 切换`g`的状态
* 解绑`g`所有绑定的数据
* 如果是`wasm`架构，直接将`g`存于空闲列表中，并开始下一次调度
* 否则，直接将`g`存于空闲列表中，如果`g`有锁定的`m`，则将`m`杀死，开始下一次调度

# 切换
## 执行完毕切换
上面说到，当goroutine执行完毕时，会执行goexit0函数，进而执行下一次调度
## 主动切换
当goroutine中阻塞的操作时，就需要让出CPU，让其他的goroutine执行。所有主动切换都是调用gopark函数来实现的。
### gopark
```go
func gopark(unlockf func(*g, unsafe.Pointer) bool, lock unsafe.Pointer, reason waitReason, traceEv byte, traceskip int) {
	if reason != waitReasonSleep {
		checkTimeouts()
	}
	mp := acquirem()
	gp := mp.curg
	status := readgstatus(gp)
	if status != _Grunning && status != _Gscanrunning {
		throw("gopark: bad g status")
	}
	// 填充相关参数
	mp.waitlock = lock
	mp.waitunlockf = unlockf
	gp.waitreason = reason
	mp.waittraceev = traceEv
	mp.waittraceskip = traceskip
	releasem(mp)
	// can't do anything that might move the G between Ms here.
	mcall(park_m)
}
```

`gopark`函数主要流程：
* 获取当前`m`绑定的`gp`
* 填充相关参数
* 利用`g0`调用`park_m`函数

```go
func park_m(gp *g) {
	_g_ := getg()

	casgstatus(gp, _Grunning, _Gwaiting)
	dropg() // 解绑g和m

	if fn := _g_.m.waitunlockf; fn != nil {
		ok := fn(gp, _g_.m.waitlock) // 尝试调用解锁函数
		_g_.m.waitunlockf = nil
		_g_.m.waitlock = nil
		if !ok {
			// 如果解锁成功
			casgstatus(gp, _Gwaiting, _Grunnable)
			execute(gp, true) // 直接执行gp
		}
	}
	schedule() // 下一次调度
}
```

`park_m`函数主要流程：
* 切换`g`的状态为等待
* 尝试解锁，如果成功则切换状态为可执行，直接调用`execute`函数执行
* 否则，进入下一个调度

### goready
当goroutine通过`gopark`函数由`_Grunning`到`_Gwaiting`，反向操作`goready`函数则是将`_Gwaiting`到`_Grunnable`。
```go
func goready(gp *g, traceskip int) {
	systemstack(func() {
		ready(gp, traceskip, true)
	})
}
```

```go
func ready(gp *g, traceskip int, next bool) {
	status := readgstatus(gp)

	_g_ := getg()
	mp := acquirem()
	// 如果不是 _Gwaiting 抛异常
	if status&^_Gscan != _Gwaiting {
		dumpgstatus(gp)
		throw("bad g->status in ready")
	}

    // 切换状态
	casgstatus(gp, _Gwaiting, _Grunnable)
	runqput(_g_.m.p.ptr(), gp, next) // 存放到本地可执行队列中
	wakep()                          // 尝试去唤起p去执行
	releasem(mp)
}
```

`ready`函数主要流程：
* 获取`gp`的状态
* 获取当前的`g`
* 检测`gp`状态是不是`_Gwaiting`
* 由`_Gwaiting`转换为`_Grunnable`状态
* 放进当前`g`的`m`的`p`中的本地可执行队列中

## 抢占切换
golang调度本质上是非抢占式的，golang利用标志位标志当前的goroutine是否可以被抢占，而触发时机是在栈扩容的时候。
golang中有个监控函数，监控着整个进程运行的相关数据，其中就包括检查某个goroutine是否占用CPU时间过长，从而进行标记抢占标记位。
```go
func sysmon() {
    // ... 省略 ...

	for {
		// ... 省略 ...

		// 解绑在陷入系统调用中的p，和抢占长时间运行的g
		if retake(now) != 0 {
			idle = 0
		} else {
			idle++
		}

		// ... 省略 ...
	}
}
```


### retake
```go
func retake(now int64) uint32 {
	n := 0
	lock(&allpLock)
	for i := 0; i < len(allp); i++ {
		_p_ := allp[i]
		if _p_ == nil {
			continue
		}
		pd := &_p_.sysmontick // sysmon 信息记录
		s := _p_.status
		sysretake := false
		if s == _Prunning || s == _Psyscall {
			// 处于 _Prunning 或者 _Psyscall 状态时，如果上一次触发调度的时间已经过去了 10ms，
			// 我们就会通过 runtime.preemptone 抢占当前处理器
			// 如果G运行时间太长则抢占G
			t := int64(_p_.schedtick)
			if int64(pd.schedtick) != t {
				pd.schedtick = uint32(t)
				pd.schedwhen = now
			} else if pd.schedwhen+forcePreemptNS <= now {
				preemptone(_p_)
				// 在_Psyscall时preemptone函数不会工作，因为m没有绑定p
				sysretake = true
			}
		}
		if s == _Psyscall {
			// 当处理器处于 _Psyscall 状态时
			// 当处理器的运行队列不为空或者不存在空闲处理器时并且当系统调用时间超过了 10ms 时
			t := int64(_p_.syscalltick)
			if !sysretake && int64(pd.syscalltick) != t {
				pd.syscalltick = uint32(t)
				pd.syscallwhen = now
				continue
			}

			if runqempty(_p_) && atomic.Load(&sched.nmspinning)+atomic.Load(&sched.npidle) > 0 && pd.syscallwhen+10*1000*1000 > now {
				// 如果_p_没有可执行的g，且有自旋的m或空闲的p，且系统调用时间没有超过10ms
				continue
			}
			// Drop allpLock so we can take sched.lock.
			unlock(&allpLock)

			// 将p的状态设置为_Pidle，计数器n加1，_p_的系统调用次数+1
			incidlelocked(-1)
			if atomic.Cas(&_p_.status, s, _Pidle) {
				n++
				_p_.syscalltick++
				handoffp(_p_) // 让 p 去找其他的事情干
			}
			incidlelocked(1)
			lock(&allpLock)
		}
	}
	unlock(&allpLock)
	return uint32(n)
}
```

`retake`函数主要流程：
* 遍历所有的`p`
* 如果`p`长时间没有调度则标记抢占标志位
* 如果`p`在系统调用中，且超过阈值时间，则解绑`p`
* 返回解绑`p`的个数

### preemptone
```go
func preemptone(_p_ *p) bool {
	mp := _p_.m.ptr()
	if mp == nil || mp == getg().m {
		// 如果mp为空，或mp是当前运行的m
		return false
	}
	gp := mp.curg
	if gp == nil || gp == mp.g0 {
		// gp 不能使 g0
		return false
	}

	gp.preempt = true // 标志gp可以被抢占

	gp.stackguard0 = stackPreempt // 直接设置为栈顶，方便触发栈扩容

	// Request an async preemption of this P.
	if preemptMSupported && debug.asyncpreemptoff == 0 {
		_p_.preempt = true // 标记p快速调度
		preemptM(mp)       // 向mp发送抢占信号
	}

	return true
}
```

### handoffp
```go
func handoffp(_p_ *p) {
	// 如果本地有可执行的G或全局可执行队列长度不为0，则直接开始执行
	if !runqempty(_p_) || sched.runqsize != 0 {
		startm(_p_, false)
		return
	}
	// 如果可以执行GC，则立即执行
	if gcBlackenEnabled != 0 && gcMarkWorkAvailable(_p_) {
		startm(_p_, false)
		return
	}
	// 如果没有自旋的m和空闲的p，并且增加自旋数成功，则让_p_绑定一个m进入自旋
	if atomic.Load(&sched.nmspinning)+atomic.Load(&sched.npidle) == 0 && atomic.Cas(&sched.nmspinning, 0, 1) {
		startm(_p_, true)
		return
	}
	lock(&sched.lock)
	if sched.gcwaiting != 0 { // 即将GC
		_p_.status = _Pgcstop
		sched.stopwait--
		if sched.stopwait == 0 {
			notewakeup(&sched.stopnote)
		}
		unlock(&sched.lock)
		return
	}
	if _p_.runSafePointFn != 0 && atomic.Cas(&_p_.runSafePointFn, 1, 0) {
		sched.safePointFn(_p_)
		sched.safePointWait--
		if sched.safePointWait == 0 {
			notewakeup(&sched.safePointNote)
		}
	}
	// 此时如果全局队列有可执行的g，则执行
	if sched.runqsize != 0 {
		unlock(&sched.lock)
		startm(_p_, false)
		return
	}
	// 如果这是最后运行的P并且没有人正在轮询网络，则需要唤醒另一个M来轮询网络。
	if sched.npidle == uint32(gomaxprocs-1) && atomic.Load64(&sched.lastpoll) != 0 {
		unlock(&sched.lock)
		startm(_p_, false)
		return
	}
	if when := nobarrierWakeTime(_p_); when != 0 {
		wakeNetPoller(when)
	}
	// 都没有则将_p_存放到空闲P列表中
	pidleput(_p_)
	unlock(&sched.lock)
}
```

`retake`函数主要流程：
* 如果`p`的本地可执行队列不为空，或全局可执行队列不为空，则绑定`m`去执行
* 如果`p`可以执行GC工作，则绑定m去执行
* 如果没有m在自旋且没有空闲的`p`，且成功设置自旋值，则获取一个`m`，进入自旋
* 如果此时在检测全局可执行队列是否为空，有则绑定`m`去执行
* 如果是最后一个正在运行的`p`，则绑定`m`去轮询网络
* 都没有则将`p`存放进空闲`p`列表

### newstack
```go
func newstack() {
	thisg := getg() // 当前执行的g

	gp := thisg.m.curg // m绑定的g

	// 判断是否抢占触发的栈扩张
	preempt := atomic.Loaduintptr(&gp.stackguard0) == stackPreempt

    // ... 省略 ...

	if preempt {
		// Act like goroutine called runtime.Gosched.
		gopreempt_m(gp) // never return
	}
    // ... 省略 ...
}
```

```go
func gopreempt_m(gp *g) {
	if trace.enabled {
		traceGoPreempt()
	}
	goschedImpl(gp)
}
```

`goschedImpl`函数就是上述Gosched函数的主要执行实体了。

如果检测到是抢占，则将m绑定的g放入全局可执行队列中。


## 系统调用切换
golang提供了系统调用接口：
```go
func Syscall(trap, a1, a2, a3 uintptr) (r1, r2 uintptr, err Errno)
func RawSyscall(trap, a1, a2, a3 uintptr) (r1, r2 uintptr, err Errno)
```

更多参数可以调用Syscall6或Syscall9。

### Syscall
```asm
TEXT	·Syscall(SB),NOSPLIT,$0-56
	CALL	runtime·entersyscall(SB)
	MOVQ	a1+8(FP), DI
	MOVQ	a2+16(FP), SI
	MOVQ	a3+24(FP), DX
	MOVQ	trap+0(FP), AX	// syscall entry
	ADDQ	$0x2000000, AX
	SYSCALL
	JCC	ok
	MOVQ	$-1, r1+32(FP)
	MOVQ	$0, r2+40(FP)
	MOVQ	AX, err+48(FP)
	CALL	runtime·exitsyscall(SB)
	RET
ok:
	MOVQ	AX, r1+32(FP)
	MOVQ	DX, r2+40(FP)
	MOVQ	$0, err+48(FP)
	CALL	runtime·exitsyscall(SB)
	RET
```

`Syscall`函数主要流程：
* 调用`runtime.entersyscall`
* 将参数存至寄存器
* 执行系统调用
* 将返回值压栈
* 调用`runtime.exitsyscall`

#### entersyscall
```go
func entersyscall() {
   reentersyscall(getcallerpc(), getcallersp())
}
```

```go
func reentersyscall(pc, sp uintptr) {
	_g_ := getg()
	_g_.m.locks++

	_g_.stackguard0 = stackPreempt // 等待被抢占
	_g_.throwsplit = true

	// Leave SP around for GC and traceback.
	save(pc, sp) // 保存现场
	_g_.syscallsp = sp
	_g_.syscallpc = pc
	casgstatus(_g_, _Grunning, _Gsyscall) // 切换状态
	if _g_.syscallsp < _g_.stack.lo || _g_.stack.hi < _g_.syscallsp {
		systemstack(func() {
			print("entersyscall inconsistent ", hex(_g_.syscallsp), " [", hex(_g_.stack.lo), ",", hex(_g_.stack.hi), "]\n")
			throw("entersyscall")
		})
	}

	if trace.enabled {
		systemstack(traceGoSysCall)
		// systemstack itself clobbers g.sched.{pc,sp} and we might
		// need them later when the G is genuinely blocked in a
		// syscall
		save(pc, sp)
	}

	if atomic.Load(&sched.sysmonwait) != 0 {
		systemstack(entersyscall_sysmon)
		save(pc, sp)
	}

	if _g_.m.p.ptr().runSafePointFn != 0 {
		// runSafePointFn may stack split if run on this stack
		systemstack(runSafePointFn)
		save(pc, sp)
	}

	_g_.m.syscalltick = _g_.m.p.ptr().syscalltick
	_g_.sysblocktraced = true
	pp := _g_.m.p.ptr()
	pp.m = 0
	_g_.m.oldp.set(pp)
	_g_.m.p = 0
	atomic.Store(&pp.status, _Psyscall) // 切换p的状态
	if sched.gcwaiting != 0 {
		systemstack(entersyscall_gcwait)
		save(pc, sp)
	}

	_g_.m.locks--
}
```

#### exitsyscall
```go
func exitsyscall() {
	_g_ := getg()

	_g_.m.locks++ 

	oldp := _g_.m.oldp.ptr()
	_g_.m.oldp = 0
	if exitsyscallfast(oldp) { // 尝试获取系统调用前绑定的p
		_g_.m.p.ptr().syscalltick++
		casgstatus(_g_, _Gsyscall, _Grunning)
		_g_.syscallsp = 0
		_g_.m.locks--
		if _g_.preempt {
			// 如果抢占，就设置stackguard0为stackPreempt
			_g_.stackguard0 = stackPreempt
		} else {
			// 否则恢复真实栈帧
			_g_.stackguard0 = _g_.stack.lo + _StackGuard
		}
		_g_.throwsplit = false

		if sched.disable.user && !schedEnabled(_g_) {
			// Scheduling of this goroutine is disabled.
			Gosched() // 开始调度
		}

		return
	}

	// 没有p被绑定的情况
	_g_.sysexitticks = 0
	_g_.m.locks--

	// Call the scheduler.
	mcall(exitsyscall0)

	_g_.syscallsp = 0
	_g_.m.p.ptr().syscalltick++
	_g_.throwsplit = false
}
```

`exitsyscall`函数主要流程：
* 获取系统调用前绑定的`oldp`
* 尝试获取`oldp`或从空闲列表获取`p`
* 如果成功获取`p`，改变相关设置，开始下一轮调度
* 如果没有获取，则调用`exitsyscall0`

```go
func exitsyscall0(gp *g) {
	_g_ := getg()

	casgstatus(gp, _Gsyscall, _Grunnable)
	dropg()
	lock(&sched.lock)
	var _p_ *p
	if schedEnabled(_g_) { // 如果可以调度_g_
		_p_ = pidleget() // 从p空闲列表中获取p
	}
	if _p_ == nil {
		globrunqput(gp) // 没有可用的p，就将gp存放于全局可执行列表中
	} else if atomic.Load(&sched.sysmonwait) != 0 {
		atomic.Store(&sched.sysmonwait, 0)
		notewakeup(&sched.sysmonnote)
	}
	unlock(&sched.lock)
	if _p_ != nil { // 如果有可用的p
		acquirep(_p_) // 直接绑定当前的m
		execute(gp, false) // 执行gp
	}
	if _g_.m.lockedg != 0 { // 如果m有锁定的g
		// Wait until another thread schedules gp and so m again.
		stoplockedm()   // 释放p，休眠m，会阻塞
		execute(gp, false) // 执行gp
	}
	stopm() // 将m休眠，并存于m空闲列表中，会阻塞
	schedule() // 下一次调度
}
```

`exitsyscall0`函数主要流程：
* 切换`gp`状态为`_Grunnable`
* 解绑`g`和`m`
* 尝试获取一个空闲的`_p_`
* 如果没有获取到就把`gp`放到全局可执行列表中
* 如果获取到了，就直接绑定当前的`m`，执行`gp`
* 如果有`m`有锁定的`g`，释放p，休眠m，等待被唤醒
* 否则`m`将放置与全局`m`空闲列表中，等待下一次调度

exitsyscall0函数如果没有p则会将m休眠

